(function(){var built=false;function build(){if(built)return;var parts=document.getElementById("lpParts");if(!parts||!parts.parentNode)return;built=true;var foot=document.createElement("div");foot.className="lp-foot";parts.parentNode.insertBefore(foot,parts);foot.appendChild(parts);var lab=document.createElement("label");lab.className="lp-lock";lab.title="Zapnuto: další sekce se odemkne, až přečteš předchozí. Vypni, pokud chceš vidět všechno najednou.";lab.innerHTML='<input type="checkbox" id="lpLockChk"> <span>Odemykat sekce postupně</span>';foot.appendChild(lab);var chk=lab.querySelector("input");chk.checked=typeof window.luxLockState==="function"?window.luxLockState():true;chk.addEventListener("change",function(){if(typeof window.luxSetLock==="function")window.luxSetLock(chk.checked)})}window.luxGameRender=function(info){build();if(info&&info.groups&&window.luxPartCount)info.groups.forEach(function(g){window.luxPartCount(g.id,g.n,g.len)});var chk=document.getElementById("lpLockChk");if(chk&&typeof window.luxLockState==="function")chk.checked=window.luxLockState()}})();